Here's a simple C++ program to find the nth Fibonacci number using recursion. I've also included a check function to demonstrate the correctness of the program with some test cases.

```cpp
#include <iostream>
#include <cassert>

// Fibonacci recursive function
int fibonacci(int n) {
    // Base case
    if (n <= 1) {
        return n;
    }
    // Recursive case
    return fibonacci(n - 1) + fibonacci(n - 2);
}

// Function to test the correctness of the fibonacci function
void check_fibonacci() {
    assert(fibonacci(0) == 0);
    assert(fibonacci(1) == 1);
    assert(fibonacci(2) == 1);
    assert(fibonacci(3) == 2);
    assert(fibonacci(4) == 3);
    assert(fibonacci(5) == 5);
    assert(fibonacci(6) == 8);
    assert(fibonacci(7) == 13);
    assert(fibonacci(8) == 21);
    assert(fibonacci(9) == 34);
    std::cout << "All test cases passed!" << std::endl;
}

int main() {
    // Run the check function to test the correctness of the fibonacci function
    check_fibonacci();
    // Ask the user for an input
    std::cout << "Enter a positive integer to find the corresponding Fibonacci number: ";
    int input;
    std::cin >> input;
    // Call the fibonacci function with the user's input and print the result
    std::cout << "The " << input << "th Fibonacci number is: " << fibonacci(input) << std::endl;
    return 0;
}
```

